function pathFromPoints(pts, closed) {
  if (!pts.length) return '';
  var d = 'M ' + pts[0].sx + ' ' + pts[0].sy;
  for (var i = 1; i < pts.length; i++) d += ' L ' + pts[i].sx + ' ' + pts[i].sy;
  if (closed) d += ' Z';
  return d;
}

function rawBoundaryPoints() {
  var u0 = state.u0, u1 = state.u0 + state.du;
  var v0 = state.v0, v1 = state.v0 + state.dv;
  var n = 64;
  var sides = { u0: [], u1: [], v0: [], v1: [], loop: [] };
  function addPoint(arr, u, v) {
    var x, y;
    try {
      x = xFn(u, v);
      y = yFn(u, v);
    } catch (err) {
      x = NaN; y = NaN;
    }
    if (isFinite(x) && isFinite(y)) arr.push({ x: x, y: y, u: u, v: v });
  }
  for (var i = 0; i < n; i++) addPoint(sides.v0, u0 + (u1 - u0) * i / (n - 1), v0);
  for (var j = 0; j < n; j++) addPoint(sides.u1, u1, v0 + (v1 - v0) * j / (n - 1));
  for (var k = 0; k < n; k++) addPoint(sides.v1, u1 - (u1 - u0) * k / (n - 1), v1);
  for (var m = 0; m < n; m++) addPoint(sides.u0, u0, v1 - (v1 - v0) * m / (n - 1));
  sides.loop = sides.v0.concat(sides.u1, sides.v1, sides.u0);
  return sides;
}

function screenMapForRaw(raw) {
  var pts = raw.loop;
  if (!pts.length) return function (p) { return { sx: right.plotLeft, sy: right.plotBottom }; };
  var minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  pts.forEach(function (p) {
    minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x);
    minY = Math.min(minY, p.y); maxY = Math.max(maxY, p.y);
  });
  if (maxX - minX < 1e-6) { maxX += 0.5; minX -= 0.5; }
  if (maxY - minY < 1e-6) { maxY += 0.5; minY -= 0.5; }
  var padX = (maxX - minX) * 0.18, padY = (maxY - minY) * 0.18;
  minX -= padX; maxX += padX; minY -= padY; maxY += padY;
  return function (p) {
    return {
      sx: right.plotLeft + (p.x - minX) / (maxX - minX) * (right.plotRight - right.plotLeft),
      sy: right.plotBottom - (p.y - minY) / (maxY - minY) * (right.plotBottom - right.plotTop)
    };
  };
}

function decorate(raw, mapper) {
  ['u0', 'u1', 'v0', 'v1', 'loop'].forEach(function (name) {
    raw[name].forEach(function (p) {
      var q = mapper(p);
      p.sx = q.sx; p.sy = q.sy;
    });
  });
}

function polygonAreaXY(points) {
  if (points.length < 3) return NaN;
  var s = 0;
  for (var i = 0; i < points.length; i++) {
    var a = points[i], b = points[(i + 1) % points.length];
    s += a.x * b.y - b.x * a.y;
  }
  return Math.abs(s) / 2;
}

function jacobianAt(u, v) {
  var h = 1e-5;
  function val(fn, a, b) {
    var z = fn(a, b);
    return isFinite(z) ? z : NaN;
  }
  var xu = (val(xFn, u + h, v) - val(xFn, u - h, v)) / (2 * h);
  var xv = (val(xFn, u, v + h) - val(xFn, u, v - h)) / (2 * h);
  var yu = (val(yFn, u + h, v) - val(yFn, u - h, v)) / (2 * h);
  var yv = (val(yFn, u, v + h) - val(yFn, u, v - h)) / (2 * h);
  return xu * yv - xv * yu;
}

function updateStats(raw) {
  var areaUV = state.du * state.dv;
  var uc = state.u0 + state.du / 2;
  var vc = state.v0 + state.dv / 2;
  var J = Math.abs(jacobianAt(uc, vc));
  var local = J * areaUV;
  var imageArea = polygonAreaXY(raw.loop);
  document.getElementById('uvAreaVal').value = fmt(areaUV);
  document.getElementById('jacobianVal').value = fmt(J);
  document.getElementById('jacAreaVal').value = fmt(local);
  rFill.attr('data-image-area', fmt(imageArea));
}

function updateLeftPanel() {
  var u0 = state.u0, u1 = state.u0 + state.du;
  var v0 = state.v0, v1 = state.v0 + state.dv;
  var ll = uvToScreen(u0, v0), lr = uvToScreen(u1, v0);
  var ul = uvToScreen(u0, v1), ur = uvToScreen(u1, v1);

  sFill.move(ul.x, ul.y).size(ur.x - ul.x, ll.y - ul.y);
  u0Line.plot(u0Line.array().valueOf([[u0Line.x1(), u0Line.y1()], [u0Line.x2(), u0Line.y2()]]));
  u0Line.plot([[ll.x, ll.y + 85], [ul.x, ul.y - 85]]);
  u1Line.plot([[lr.x, lr.y + 85], [ur.x, ur.y - 85]]);
  v0Line.plot([[ll.x - 90, ll.y], [lr.x + 90, lr.y]]);
  v1Line.plot([[ul.x - 90, ul.y], [ur.x + 90, ur.y]]);

  cornerDots.ll.center(ll.x, ll.y);
  cornerDots.lr.center(lr.x, lr.y);
  cornerDots.ul.center(ul.x, ul.y);
  cornerDots.ur.center(ur.x, ur.y);

  sLabel.center((ll.x + ur.x) / 2, (ll.y + ur.y) / 2);
  u0Label.center(ul.x, ul.y - 126);
  u1Label.center(ur.x + 18, ur.y - 126);
  v0Label.move(lr.x + 95, lr.y - 28);
  v1Label.move(ur.x + 95, ur.y - 42);
  cornerLabel.move(ll.x - 175, ll.y + 34);
  duLabel.center((ll.x + lr.x) / 2, ll.y + 47);
  dvLabel.move(lr.x + 23, (lr.y + ur.y) / 2 - 33);
}

function updateImage() {
  updateLeftPanel();
  var raw = rawBoundaryPoints();
  var mapper = screenMapForRaw(raw);
  decorate(raw, mapper);

  rFill.plot(pathFromPoints(raw.loop, true));
  boundaryU0.plot(pathFromPoints(raw.u0, false));
  boundaryU1.plot(pathFromPoints(raw.u1, false));
  boundaryV0.plot(pathFromPoints(raw.v0, false));
  boundaryV1.plot(pathFromPoints(raw.v1, false));

  updateStats(raw);
  applyStepVisuals();
}

function setTransformFn(which, fn) {
  if (which === 'x') xFn = fn;
  if (which === 'y') yFn = fn;
  updateImage();
}

bindEquationInput('xFormulaInput', function (fn) { setTransformFn('x', fn); }, { variables: ['u', 'v'] });
bindEquationInput('yFormulaInput', function (fn) { setTransformFn('y', fn); }, { variables: ['u', 'v'] });

var dragging = null;
Object.keys(cornerDots).forEach(function (key) {
  var dot = cornerDots[key];
  dot.css('cursor', 'grab')
    .on('mousemove', function (e) { showTooltip('Drag this corner to change u₀, v₀, Δu, and Δv.', e); })
    .on('mouseleave', hideTooltip)
    .on('mousedown', function (e) {
      dragging = key;
      dot.css('cursor', 'grabbing');
      e.preventDefault();
      e.stopPropagation();
    })
    .on('click', function () {
      showPopup('Dragging the rectangle', 'Changing the rectangle samples a different part of the same transformation. As S gets smaller, |J| at the rectangle becomes a better estimate of the area-scaling factor.');
    });
});

function svgPoint(evt) {
  var pt = draw.node.createSVGPoint();
  pt.x = evt.clientX;
