function rawBoundaryPoints() {
  var u0 = state.u0, u1 = state.u0 + state.du;
  var v0 = state.v0, v1 = state.v0 + state.dv;
  var n = 90;
  var sides = { u0: [], u1: [], v0: [], v1: [], loop: [] };
  for (var i = 0; i < n; i++) addRawPoint(sides.v0, u0 + (u1 - u0) * i / (n - 1), v0);
  for (var j = 0; j < n; j++) addRawPoint(sides.u1, u1, v0 + (v1 - v0) * j / (n - 1));
  for (var k = 0; k < n; k++) addRawPoint(sides.v1, u1 - (u1 - u0) * k / (n - 1), v1);
  for (var m = 0; m < n; m++) addRawPoint(sides.u0, u0, v1 - (v1 - v0) * m / (n - 1));
  sides.loop = sides.v0.concat(sides.u1, sides.v1, sides.u0);
  return sides;
}

function screenMapForRaw(raw) {
  var pts = raw.loop;
  if (!pts.length) {
    return function () { return { sx: (right.plotLeft + right.plotRight) / 2, sy: (right.plotTop + right.plotBottom) / 2 }; };
  }
  var minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  pts.forEach(function (p) {
    minX = Math.min(minX, p.x);
    maxX = Math.max(maxX, p.x);
    minY = Math.min(minY, p.y);
    maxY = Math.max(maxY, p.y);
  });
  if (maxX - minX < 1e-6) { minX -= 0.5; maxX += 0.5; }
  if (maxY - minY < 1e-6) { minY -= 0.5; maxY += 0.5; }
  var padX = (maxX - minX) * 0.16;
  var padY = (maxY - minY) * 0.16;
  minX -= padX; maxX += padX; minY -= padY; maxY += padY;
  return function (p) {
    return {
      sx: right.plotLeft + (p.x - minX) / (maxX - minX) * (right.plotRight - right.plotLeft),
      sy: right.plotBottom - (p.y - minY) / (maxY - minY) * (right.plotBottom - right.plotTop)
    };
  };
}

