function addRawPoint(arr, u, v) {
  var x, y;
  try {
    x = xFn(u, v);
    y = yFn(u, v);
  } catch (err) {
    x = NaN;
    y = NaN;
  }
  if (isFinite(x) && isFinite(y)) arr.push({ x: x, y: y, u: u, v: v });
}

function rawBoundaryPoints() {
  var u0 = state.u0, u1 = state.u0 + state.du;
  var v0 = state.v0, v1 = state.v0 + state.dv;
  var n = 150;
  var extU = Math.max(0.22, state.du * 0.34);
  var extV = Math.max(0.18, state.dv * 0.25);
  var ue0 = clamp(u0 - extU, uv.uMin, uv.uMax);
  var ue1 = clamp(u1 + extU, uv.uMin, uv.uMax);
  var ve0 = clamp(v0 - extV, uv.vMin, uv.vMax);
  var ve1 = clamp(v1 + extV, uv.vMin, uv.vMax);

  var sides = { u0: [], u1: [], v0: [], v1: [], loop: [], extAll: [] };

  for (var i = 0; i < n; i++) addRawPoint(sides.v0, ue0 + (ue1 - ue0) * i / (n - 1), v0);
  for (var j = 0; j < n; j++) addRawPoint(sides.u1, u1, ve0 + (ve1 - ve0) * j / (n - 1));
  for (var k = 0; k < n; k++) addRawPoint(sides.v1, ue0 + (ue1 - ue0) * k / (n - 1), v1);
  for (var m = 0; m < n; m++) addRawPoint(sides.u0, u0, ve0 + (ve1 - ve0) * m / (n - 1));

  var finiteV0 = [], finiteU1 = [], finiteV1 = [], finiteU0 = [];
  for (var a = 0; a < n; a++) addRawPoint(finiteV0, u0 + (u1 - u0) * a / (n - 1), v0);
  for (var b = 0; b < n; b++) addRawPoint(finiteU1, u1, v0 + (v1 - v0) * b / (n - 1));
  for (var c = 0; c < n; c++) addRawPoint(finiteV1, u1 - (u1 - u0) * c / (n - 1), v1);
  for (var d = 0; d < n; d++) addRawPoint(finiteU0, u0, v1 - (v1 - v0) * d / (n - 1));

  sides.loop = finiteV0.concat(finiteU1, finiteV1, finiteU0);
  sides.extAll = sides.u0.concat(sides.u1, sides.v0, sides.v1, sides.loop);
  return sides;
}

function screenMapForRaw(raw) {
  var pts = raw.extAll && raw.extAll.length ? raw.extAll : raw.loop;
  if (!pts || !pts.length) {
    return function () { return { sx: 1565, sy: 300 }; };
  }

  if (isDefaultPolar()) {
    var minxOk = true, maxX = 0, maxY = 0;
    for (var q = 0; q < pts.length; q++) {
      if (pts[q].x < -0.04 || pts[q].y < -0.04) minxOk = false;
      maxX = Math.max(maxX, pts[q].x);
      maxY = Math.max(maxY, pts[q].y);
    }
    if (minxOk && maxX <= 2.55 && maxY <= 2.25) {
      var scaleX = (right.plotRight - right.axisX) / 2.15;
      var scaleY = (right.axisY - right.plotTop) / 2.05;
      return function (p) {
        return { sx: right.axisX + p.x * scaleX, sy: right.axisY - p.y * scaleY };
      };
    }
  }

  var minX = Infinity, maxX2 = -Infinity, minY = Infinity, maxY2 = -Infinity;
  pts.forEach(function (p) {
    minX = Math.min(minX, p.x);
    maxX2 = Math.max(maxX2, p.x);
    minY = Math.min(minY, p.y);
    maxY2 = Math.max(maxY2, p.y);
  });
  if (maxX2 - minX < 1e-6) { minX -= 0.5; maxX2 += 0.5; }
  if (maxY2 - minY < 1e-6) { minY -= 0.5; maxY2 += 0.5; }
  var padX = (maxX2 - minX) * 0.14;
  var padY = (maxY2 - minY) * 0.14;
  minX -= padX; maxX2 += padX; minY -= padY; maxY2 += padY;
  return function (p) {
    return {
      sx: right.plotLeft + (p.x - minX) / (maxX2 - minX) * (right.plotRight - right.plotLeft),
      sy: right.plotBottom - (p.y - minY) / (maxY2 - minY) * (right.plotBottom - right.plotTop)
    };
  };
}

function decorate(raw, mapper) {
  ['u0', 'u1', 'v0', 'v1', 'loop', 'extAll'].forEach(function (name) {
    raw[name].forEach(function (p) {
      var q = mapper(p);
      p.sx = q.sx;
      p.sy = q.sy;
    });
  });
}

function polygonAreaXY(points) {
  if (!points || points.length < 3) return NaN;
  var s = 0;
  for (var i = 0; i < points.length; i++) {
    var a = points[i], b = points[(i + 1) % points.length];
    s += a.x * b.y - b.x * a.y;
  }
  return Math.abs(s) / 2;
}

function jacobianAt(u, v) {
  var h = 1e-5;
  function val(fn, a, b) {
    var z = fn(a, b);
    return isFinite(z) ? z : NaN;
  }
  var xu = (val(xFn, u + h, v) - val(xFn, u - h, v)) / (2 * h);
  var xv = (val(xFn, u, v + h) - val(xFn, u, v - h)) / (2 * h);
  var yu = (val(yFn, u + h, v) - val(yFn, u - h, v)) / (2 * h);
  var yv = (val(yFn, u, v + h) - val(yFn, u, v - h)) / (2 * h);
  return xu * yv - xv * yu;
}

function updateStats(raw) {
  var areaUV = state.du * state.dv;
  var uc = state.u0 + state.du / 2;
  var vc = state.v0 + state.dv / 2;
  var J = Math.abs(jacobianAt(uc, vc));
  var local = J * areaUV;
  var imageArea = polygonAreaXY(raw.loop);
  document.getElementById('uvAreaVal').value = fmt(areaUV);
  document.getElementById('jacobianVal').value = fmt(J);
  document.getElementById('jacAreaVal').value = fmt(local);
  document.getElementById('imageAreaVal').value = fmt(imageArea);
}

function updateLeftPanel() {
  var u0 = state.u0, u1 = state.u0 + state.du;
  var v0 = state.v0, v1 = state.v0 + state.dv;
  var ll = uvToScreen(u0, v0), lr = uvToScreen(u1, v0);
  var ul = uvToScreen(u0, v1), ur = uvToScreen(u1, v1);

