  cornerDots.lr.center(lr.x, lr.y);
  cornerDots.ul.center(ul.x, ul.y);
  cornerDots.ur.center(ur.x, ur.y);

  sLabel.center((ll.x + ur.x) / 2, (ll.y + ur.y) / 2);
  u0Label.center(ul.x - 6, ul.y - 126);
  u1Label.center(ur.x + 18, ur.y - 126);
  v1Label.move(ur.x + 96, ur.y - 35);
  v0Label.move(lr.x + 96, lr.y - 27);
  cornerLabel.move(ll.x - 178, ll.y + 28);
  duLabel.center((ll.x + lr.x) / 2, ll.y + 47);
  dvLabel.move(lr.x + 22, (lr.y + ur.y) / 2 - 30);
}

function updateImage() {
  updateLeftPanel();
  var raw = rawBoundaryPoints();
  decorate(raw, screenMapForRaw(raw));

  rFill.attr('d', pathFromPoints(raw.loop, true));
  boundaryU0.attr('d', pathFromPoints(raw.u0, false));
  boundaryU1.attr('d', pathFromPoints(raw.u1, false));
  boundaryV0.attr('d', pathFromPoints(raw.v0, false));
  boundaryV1.attr('d', pathFromPoints(raw.v1, false));

  if (raw.loop.length) {
    var cx = 0, cy = 0;
    raw.loop.forEach(function (p) { cx += p.sx; cy += p.sy; });
    rLabel.center(cx / raw.loop.length, cy / raw.loop.length);
  }

  updateStats(raw);
  applyStepVisuals();
  labelLayer.front();
}

function setTransformFn(which, fn, src) {
  if (which === 'x') {
    xFn = fn;
    formulaSrc.x = src || formulaSrc.x;
  }
  if (which === 'y') {
    yFn = fn;
    formulaSrc.y = src || formulaSrc.y;
  }
  updateImage();
}

var dragging = null;
Object.keys(cornerDots).forEach(function (key) {
  var dot = cornerDots[key];
  dot.css('cursor', 'grab')
