    });
});

function svgPoint(evt) {
  var pt = draw.node.createSVGPoint();
  pt.x = evt.clientX;
  pt.y = evt.clientY;
  return pt.matrixTransform(draw.node.getScreenCTM().inverse());
}

document.addEventListener('mousemove', function (e) {
  if (!dragging) return;
  var p = svgPoint(e);
  var q = screenToUv(p.x, p.y);
  var minW = 0.18, minH = 0.14;
  var u0 = state.u0, u1 = state.u0 + state.du;
  var v0 = state.v0, v1 = state.v0 + state.dv;

  if (dragging === 'll') {
    u0 = clamp(q.u, uv.uMin, u1 - minW);
    v0 = clamp(q.v, uv.vMin, v1 - minH);
  } else if (dragging === 'lr') {
    u1 = clamp(q.u, u0 + minW, uv.uMax);
    v0 = clamp(q.v, uv.vMin, v1 - minH);
  } else if (dragging === 'ul') {
    u0 = clamp(q.u, uv.uMin, u1 - minW);
    v1 = clamp(q.v, v0 + minH, uv.vMax);
  } else if (dragging === 'ur') {
    u1 = clamp(q.u, u0 + minW, uv.uMax);
    v1 = clamp(q.v, v0 + minH, uv.vMax);
  }

  state.u0 = u0;
  state.v0 = v0;
  state.du = u1 - u0;
  state.dv = v1 - v0;
  updateImage();
});

document.addEventListener('mouseup', function () {
